USE [master];SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @T sysname=N'$(TargetDatabase)',@L sysname,@S nvarchar(max);SELECT @L=name FROM sys.master_files WHERE database_id=DB_ID(@T) AND type=1;IF @L IS NULL THROW 51002,'FAIL_STATE: STL-008-Logdatei fehlt.',1;SET @S=N'ALTER DATABASE '+QUOTENAME(@T)+N' MODIFY FILE(NAME='+QUOTENAME(@L,N'''')+N',FILEGROWTH=64MB);';EXEC(@S);PRINT 'SQLPERF_SUMMARY|PASS|OK';
